Review this React hook change:

```ts
export function useCustomerRisk(customerId: string, includeHistory: boolean) {
  const [risk, setRisk] = useState<Risk | null>(null);
  useEffect(() => {
    setRisk(null);
    fetchRisk(customerId, { includeHistory }).then(setRisk);
  }, [customerId]);
  return risk;
}
```

The old version used AbortController cleanup and included both customerId and includeHistory in dependencies.
